-- Trigger para INSERT: guardar nuevo departamento en historial
CREATE TRIGGER department_after_insert
AFTER INSERT ON departments
FOR EACH ROW
INSERT INTO department_history (
  departmentId, name, description, code, parentId, managerId, isActive, changeType, changedBy
) VALUES (
  NEW.id, NEW.name, NEW.description, NEW.code, NEW.parentId, NEW.managerId, NEW.isActive, 'created', NULL
);

-- Trigger para UPDATE: guardar cambios en historial
CREATE TRIGGER department_after_update
AFTER UPDATE ON departments
FOR EACH ROW
INSERT INTO department_history (
  departmentId, name, description, code, parentId, managerId, isActive, changeType, changedBy
) VALUES (
  NEW.id, NEW.name, NEW.description, NEW.code, NEW.parentId, NEW.managerId, NEW.isActive, 'updated', NULL
);

-- Trigger para DELETE: marcar eliminación en historial
CREATE TRIGGER department_after_delete
AFTER DELETE ON departments
FOR EACH ROW
INSERT INTO department_history (
  departmentId, name, description, code, parentId, managerId, isActive, changeType, changedBy
) VALUES (
  OLD.id, OLD.name, OLD.description, OLD.code, OLD.parentId, OLD.managerId, OLD.isActive, 'deleted', NULL
);

